package m

import "testing"

func TestDouble(t *testing.T) {
	if Double(3) != 6 {
		t.Fatal("bad")
	}
}

func TestGroup(t *testing.T) {
	t.Run("one", func(t *testing.T) {
		t.Log("a message")
		t.Run("nested", func(t *testing.T) {})
	})
	t.Run("two", func(t *testing.T) {
		t.Logf("value %d", Double(2))
	})
}

func TestSkip(t *testing.T) { t.Skip("not now") }

