var test = []I{
	Int8(0x01),
	Uint8(0x01),
	Int16(0x0102),
	Uint16(0x0102),
	Int32(0x01020304),
	Uint32(0x01020304),
	Int64(0x0102030405060708),
	Uint64(0x0102030405060708),
}

func main() {
	for _, t := range test {
		t.m(0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17)
	}
}

var bug = false

func check(desc string, have, want int64, a, b, c, d, e, f, g, h byte) {
	if have != want || a != 0x10 || b != 0x11 || c != 0x12 || d != 0x13 || e != 0x14 || f != 0x15 || g != 0x16 || h != 0x17 {
		if !bug {
			bug = true
			println("BUG")
		}
		println(desc, "check", have, want, a, b, c, d, e, f, g, h)
	}
}

package main

func init() {
	v := []int{-86300, 473715, -14044, 332091, 748126, 732675, -461842, 525475}
	m := map[int]int{}
	s := 10874
	for i, x := range v {
		m[i] = x ^ (s << 1)
		s = s*131 + x + len(m)
	}
	f := func(k int) int { return m[k] + k*29 }
	for i := range v {
		s ^= f(i)
	}
	t := ""
	for _, x := range v {
		if x&1 == 0 {
			t += "e"
		} else {
			t += "o"
		}
	}
	println("wit", s, t, len(m))
}

